package com.wizzadrds.theworldremembers.equipment; import com.mojang.serialization.Codec; import net.minecraft.resources.Identifier; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.entity.EquipmentSlot; import net.minecraft.world.entity.npc.villager.Villager; import net.minecraft.world.level.saveddata.SavedData; import net.minecraft.world.level.saveddata.SavedDataType; import java.util.*; public final class NpcEquipmentManager extends SavedData{private final Map<UUID,NpcEquipment> data=new HashMap<>(); private static final Codec<NpcEquipmentManager>C=Codec.unboundedMap(Codec.STRING.xmap(UUID::fromString,UUID::toString),NpcEquipment.CODEC).xmap(m->{var x=new NpcEquipmentManager();x.data.putAll(m);return x;},x->x.data); private static final SavedDataType<NpcEquipmentManager>TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath("the_world_remembers","equipment"),NpcEquipmentManager::new,C,null); public static NpcEquipmentManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new NpcEquipmentManager():l.getDataStorage().computeIfAbsent(TYPE);} public NpcEquipment get(UUID id){return data.get(id);} public void sync(Villager v){data.put(v.getUUID(),new NpcEquipment(id(v,EquipmentSlot.MAINHAND),id(v,EquipmentSlot.HEAD),id(v,EquipmentSlot.CHEST),id(v,EquipmentSlot.LEGS),id(v,EquipmentSlot.FEET)));setDirty();} private static String id(Villager v,EquipmentSlot s){var x=v.getItemBySlot(s);return x.isEmpty()?"minecraft:air":net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(x.getItem()).toString();}}
